Add-Type -AssemblyName System.IO.Compression.FileSystem; function Analyze-Apk { param();  = [System.IO.Compression.ZipFile]::OpenRead();  = .Entries | Group-Object { if (.FullName -match " ^res/\) { \res\ } elseif (.FullName -match \^lib/\) { \lib\ } elseif (.FullName -match \^classes.*\.dex\) { \dex\ } elseif (.FullName -match \^META-INF/\) { \META-INF\ } else { .Name } } | Select-Object Name, @{N=\SizeMB\;E={[math]::Round((.Group | Measure-Object Length -Sum).Sum / 1MB, 2)}}; .Dispose(); return }; Write-Host \DEBUG:\; Analyze-Apk \app/build/outputs/apk/debug/app-debug.apk\ | Format-Table -AutoSize; Write-Host \RELEASE:\; Analyze-Apk \app/build/outputs/apk/release/app-release.apk\ | Format-Table -AutoSize;
